import Accelerate
import Foundation

/// The four sample-level audio effects the model carries and AVFoundation
/// cannot express: pan, the mono fold, the compressor and broadband noise
/// reduction (spec §4.2, §5.2's `AudioProps`).
///
/// **Why this file has no AVFoundation in it.** Volume, the fades and ducking
/// are a gain CURVE, so `audio.rs` folds them into one envelope per
/// composition track and `AVMutableAudioMixInputParameters` plays it back as
/// volume ramps. These four cannot be a curve: pan and the mono fold need
/// every channel at once to write to, and the compressor and the noise reducer
/// are functions of the samples rather than of the clock. So they are real
/// DSP, they run in Swift,
/// and they live here — plain buffers in, plain buffers out, no player, no
/// reader, no tap. `AudioTap.swift` is the only file that knows where the
/// buffers come from, which is what lets the SAME code serve the preview and
/// the export (§7.2's one-movie-one-description rule).
///
/// **Real-time discipline.** Everything runs inside
/// `MTAudioProcessingTap`'s process callback, on a thread that must not
/// block: every buffer these types touch is allocated once in `init` and
/// never grown, nothing here takes a lock, and no Swift value that could
/// allocate is created per sample. `frames` is never larger than the
/// `maxFrames` the chain was built with.
///
/// **Transparency is a property of the CALLER, not of these types.** With
/// pan 0, mono off, no compressor and noise reduction 0 the chain is still a
/// chain, and
/// running audio through the noise reducer's FFT round trip would change the
/// low bits even though it changes nothing audible. So `CompositionBuilder`
/// installs no tap at all on a track whose every clip is inert
/// (`AudioClipDSP.isInert`), and such a track's samples are the ones today's
/// build produces, byte for byte.
enum AudioDSP {
    /// Below this the compressor's detector is treated as silence rather than
    /// fed to `log10`, which would otherwise return -inf and poison the
    /// envelope. -180 dBFS: far under any 24-bit source's noise floor.
    static let silenceFloor: Float = 1e-9

    /// dB → linear gain, and the constant that turns a dB difference into an
    /// exponent for `expf` (ln 10 / 20). One `expf` per sample is cheaper than
    /// one `powf`.
    static let dbToExponent: Float = 0.115_129_254_649_702_28

    static func gain(fromDecibels db: Float) -> Float { expf(db * dbToExponent) }
}

// MARK: - Parameters

/// The compressor's settings in the units the DSP works in.
///
/// The model spells the two time constants in TICKS, like every other time in
/// the schema (`core/src/model.rs`'s `Compressor`). They become seconds
/// exactly once, in `AudioClipDSP`'s conversion, so nothing below this line
/// ever sees a tick — the rule the slice was written to.
struct AudioCompressorSettings: Equatable {
    /// dBFS above which gain reduction starts, clamped to the model's -60…0.
    var thresholdDB: Double
    /// N:1. 1 is no reduction at all (the makeup still applies), 20 is
    /// effectively a limiter.
    var ratio: Double
    /// Seconds for the reduction to close on a level that just rose.
    var attackSeconds: Double
    /// Seconds for it to open again on a level that just fell.
    var releaseSeconds: Double
    /// dB added after the reduction, to win back what it took.
    var makeupDB: Double

    init(
        thresholdDB: Double, ratio: Double, attackSeconds: Double, releaseSeconds: Double,
        makeupDB: Double
    ) {
        // A hand-edited project can carry anything; the op's own range checks
        // (`props_check.rs`'s `check_audio`) only cover what the app wrote.
        self.thresholdDB = thresholdDB.isFinite ? Swift.min(Swift.max(thresholdDB, -60), 0) : -18
        self.ratio = ratio.isFinite ? Swift.min(Swift.max(ratio, 1), 20) : 1
        self.attackSeconds = attackSeconds.isFinite ? Swift.max(attackSeconds, 0) : 0
        self.releaseSeconds = releaseSeconds.isFinite ? Swift.max(releaseSeconds, 0) : 0
        self.makeupDB = makeupDB.isFinite ? Swift.min(Swift.max(makeupDB, 0), 24) : 0
    }
}

/// One clip's worth of sample-level audio settings — everything the model
/// carries that the composition plan cannot.
///
/// A composition audio track holds many clips one after another (§7.2), so
/// these change at every cut on the track; `AudioTap` looks the right one up
/// by the buffer's own timestamp.
struct AudioClipDSP: Equatable {
    /// -1 hard left … +1 hard right. See `AudioPanLaw`.
    var pan: Double
    var compressor: AudioCompressorSettings?
    /// 0 off … 1 the most subtraction this build will do.
    var noiseReduction: Double
    /// `AudioProps.mono`: average every channel into all of them. It rides
    /// here rather than in the plan because the plan carries nothing a
    /// property edit changes, and because the per-clip sample-level settings
    /// already travel this way, keyed by clip id.
    var mono: Bool
    /// The same fold, asked for by a nest clip this one is INSIDE, and run at
    /// the tail of the chain rather than at the head of the Mix stage.
    ///
    /// **Why it is a second flag rather than the same one.** A nest clip's
    /// `mono` is a statement about the nest's MIX, and the mix is a sum: the
    /// fold is linear, so folding every contributor separately and adding
    /// them gives exactly the same samples as adding them and folding once —
    /// but only if each contributor is folded after everything IT does to its
    /// own channels. Folding at the head instead would put the inner clip's
    /// own pan after the nest's fold, and a hard-left clip inside a folded
    /// nest would come out hard left, which is not mono at all. The plan's
    /// envelope is a scalar per track and applies to every channel equally,
    /// so it commutes with the fold and may stay downstream of the tap.
    var enclosingMono: Bool

    init(
        pan: Double = 0, compressor: AudioCompressorSettings? = nil, noiseReduction: Double = 0,
        mono: Bool = false, enclosingMono: Bool = false
    ) {
        self.pan = pan.isFinite ? Swift.min(Swift.max(pan, -1), 1) : 0
        self.compressor = compressor
        self.noiseReduction =
            noiseReduction.isFinite ? Swift.min(Swift.max(noiseReduction, 0), 1) : 0
        // No clamping: a bool has no range.
        self.mono = mono
        self.enclosingMono = enclosingMono
    }

    /// The settings that change nothing. A composition track on which every
    /// clip is inert gets no tap, which is what makes an untouched project's
    /// audio bit-identical to the build before this file existed.
    static let inert = AudioClipDSP()

    /// True when this clip asks for no sample work whatsoever. `pan == 0` is
    /// exact rather than approximate on purpose: the pan law is unity at the
    /// centre, so 0 and "nearly 0" differ by nothing audible, and treating a
    /// hand-written 1e-18 as active costs one silent multiply rather than a
    /// wrong answer.
    var isInert: Bool {
        pan == 0 && compressor == nil && noiseReduction <= 0 && !mono && !enclosingMono
    }
}

// MARK: - Pan

/// The pan law: constant power, normalised to unity at the centre.
///
/// **Why constant power.** Two uncorrelated channels sum by POWER, so a law
/// that keeps `L² + R²` constant is the one that holds perceived loudness
/// across the sweep; the linear law (`L = 1 - t`, `R = t`) drops 6 dB in the
/// middle and sounds like a dip as the clip crosses the centre.
///
/// **Why normalised to unity rather than to the edges.** The textbook
/// constant-power law puts 0.707 in both channels at the centre — a 3 dB cut
/// applied to every clip whose pan is 0, which is every clip in every project
/// that has ever been opened in this app. Multiplying the pair by √2 moves
/// the unity point to the centre instead, so pan 0 is EXACTLY a no-op
/// (`gains(0) == (1, 1)` is asserted, not hoped for) and the price is paid at
/// the extremes, where a hard-panned clip is 3 dB louder in the channel it
/// went to. That is the right trade for an editor: the common case is
/// transparent and the loud case is one the user chose.
///
/// **On a stereo clip this is a BALANCE.** Applying one gain to L and another
/// to R does not move a stereo image the way panning a mono source into a
/// stereo bus does; it leans it. That is what every editor's clip-level pan
/// does, and folding to mono first to get a "true" pan would throw away the
/// stereo the clip was recorded with.
///
/// **On a clip that asks for `mono` it is a TRUE pan**, and that is the
/// honest description rather than a special case: the fold runs at the head of
/// the Mix stage, immediately before this, so both channels hold the same
/// signal and leaning them moves one source between two speakers. It is also
/// why the fold cannot go after the pan — `(g_L·x + g_R·x)/2 = ((g_L+g_R)/2)·x`
/// is the same signal in both channels at every pan position, so the control
/// would degrade into a gain change and read as broken. A fold an enclosing
/// NEST clip asks for DOES run after this pan, and is not that case: it folds
/// the nest's mix, and flattening whatever panning happens inside the nest is
/// precisely what that means (`AudioDSPChain`).
///
/// **A mono composition track cannot be panned at all** — measured, not
/// assumed: a tap on a track whose source is mono is prepared with one
/// channel, and the upmix to stereo happens downstream of it. There is no
/// second channel to write to, so pan on such a clip is inaudible; see
/// `AudioDSPChain.process`.
enum AudioPanLaw {
    static func gains(_ pan: Double) -> (left: Float, right: Float) {
        guard pan.isFinite, pan != 0 else { return (1, 1) }
        let clamped = min(max(pan, -1), 1)
        // 0 … π/2 as the pan runs left … right.
        let theta = (clamped + 1) * Double.pi / 4
        return (Float(cos(theta) * 2.0.squareRoot()), Float(sin(theta) * 2.0.squareRoot()))
    }
}

// MARK: - Compressor

/// A feed-forward peak compressor with a hard knee, channel-linked.
///
/// **Linked, not per channel.** The detector is the largest absolute sample
/// across the channels and one gain is applied to all of them. Compressing
/// each channel on its own detector makes the stereo image wander whenever
/// one side is louder, which is the classic way a compressor ruins a mix.
///
/// **One compressor per composition TRACK, not per clip.** A composition
/// audio track is a sequence of clips (§7.2) and this sits on it like a
/// channel-strip insert: the settings change at each cut, the envelope
/// carries across it. Restarting the envelope per clip would make every cut
/// audible as a jump in gain reduction.
///
/// The envelope is a one-pole smoother on the gain reduction in dB, which is
/// the standard shape: `attack` is how fast the reduction closes on a level
/// that just rose, `release` how fast it opens again.
final class AudioCompressorStage {
    /// Current gain reduction in dB, always ≥ 0. Persists across buffers.
    private var reductionDB: Float = 0
    /// The peak follower's state — see `processChunk`. Also persists.
    private var detectorState: Float = 0
    private let sampleRate: Double
    /// The linked detector and the per-sample gain, sized once.
    private let detector: UnsafeMutablePointer<Float>
    private let scratch: UnsafeMutablePointer<Float>
    private let gains: UnsafeMutablePointer<Float>
    private let capacity: Int

    init(sampleRate: Double, maxFrames: Int) {
        self.sampleRate = sampleRate > 0 ? sampleRate : 48000
        capacity = max(1, maxFrames)
        detector = .allocate(capacity: capacity)
        scratch = .allocate(capacity: capacity)
        gains = .allocate(capacity: capacity)
        detector.initialize(repeating: 0, count: capacity)
        scratch.initialize(repeating: 0, count: capacity)
        gains.initialize(repeating: 1, count: capacity)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AudioCompressorStage does not support NSCoder")
    }

    deinit {
        detector.deallocate()
        scratch.deallocate()
        gains.deallocate()
    }

    /// Forgets the envelope and the follower. Called when playback restarts,
    /// so a paused-then-resumed preview does not open with the reduction the
    /// last buffer left.
    func reset() {
        reductionDB = 0
        detectorState = 0
    }

    /// A one-pole coefficient for a time constant in seconds. Zero seconds
    /// means "instantly", which is a legitimate setting (a brick-wall attack)
    /// and must not divide by zero.
    private func coefficient(_ seconds: Double) -> Float {
        guard seconds > 0 else { return 1 }
        return Float(1 - exp(-1 / (seconds * sampleRate)))
    }

    /// Compresses `frames` samples in place across `count` channels.
    ///
    /// `settings` of nil means this clip asks for no compression: the target
    /// reduction is 0 but the envelope still RELEASES toward it, so a cut from
    /// a compressed clip to an uncompressed one opens up over the last
    /// clip's release time instead of stepping.
    func process(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int, settings: AudioCompressorSettings?
    ) {
        guard frames > 0, count > 0 else { return }
        // `maxFrames` is what `prepare` promised, not a guarantee: a buffer
        // bigger than the scratch is split rather than dropped, because
        // silently leaving audio unprocessed is the one outcome worth ruling
        // out.
        var offset = 0
        while offset < frames {
            let chunk = min(capacity, frames - offset)
            processChunk(channels, count: count, offset: offset, frames: chunk, settings: settings)
            offset += chunk
        }
    }

    private func processChunk(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        offset: Int, frames: Int, settings: AudioCompressorSettings?
    ) {
        // The linked detector: |x| of the first channel, then the running
        // maximum against every other. Vectorised — this is two passes over
        // the buffer rather than a branch per sample per channel.
        var wrote = false
        for channel in 0..<count {
            guard let data = channels[channel] else { continue }
            if !wrote {
                vDSP_vabs(data + offset, 1, detector, 1, vDSP_Length(frames))
                wrote = true
            } else {
                vDSP_vabs(data + offset, 1, scratch, 1, vDSP_Length(frames))
                vDSP_vmax(detector, 1, scratch, 1, detector, 1, vDSP_Length(frames))
            }
        }
        guard wrote else { return }

        let thresholdDB = Float(settings?.thresholdDB ?? 0)
        let ratio = Float(settings?.ratio ?? 1)
        // How much of every dB above the threshold is given back. Ratio 1
        // (or no compressor at all) makes this 0 and the stage a pure makeup
        // gain, which is exactly what 1:1 means.
        let slope = ratio > 1 ? 1 - 1 / ratio : 0
        let makeupDB = Float(settings?.makeupDB ?? 0)
        let thresholdLinear = AudioDSP.gain(fromDecibels: thresholdDB)
        let attack = coefficient(settings?.attackSeconds ?? 0)
        let release = coefficient(settings?.releaseSeconds ?? 0)
        // The detector is a PEAK FOLLOWER — it jumps to each new peak and
        // falls back at the release rate — rather than the raw |x|. A naive
        // detector reads a waveform's own zero crossings as the level
        // collapsing, so the gain is modulated at twice the signal's
        // frequency: audible as distortion on anything low, and the reason a
        // sine measured through a textbook 3:1 lands a few tenths of a dB
        // shy of where the arithmetic says it should. The floor keeps a
        // zero-release setting from turning the follower back into |x|.
        let fall = Float(exp(-1 / (max(settings?.releaseSeconds ?? 0, 0.010) * sampleRate)))

        for index in 0..<frames {
            detectorState = max(detector[index], detectorState * fall)
            let level = detectorState
            // The log is skipped entirely below the threshold, which is where
            // most samples of most material are.
            var target: Float = 0
            if slope > 0, level > thresholdLinear {
                let levelDB = 20 * log10f(max(level, AudioDSP.silenceFloor))
                target = (levelDB - thresholdDB) * slope
            }
            let coefficient = target > reductionDB ? attack : release
            reductionDB += (target - reductionDB) * coefficient
            gains[index] = AudioDSP.gain(fromDecibels: makeupDB - reductionDB)
        }

        for channel in 0..<count {
            guard let data = channels[channel] else { continue }
            vDSP_vmul(data + offset, 1, gains, 1, data + offset, 1, vDSP_Length(frames))
        }
    }
}

// MARK: - Noise reduction

/// Broadband noise reduction, one instance per channel: a short-time spectral
/// attenuator over a noise floor the signal itself is measured for.
///
/// **What it actually does**, spelled out so that neither this comment nor the
/// pane's label can overstate it. The signal is cut into 512-sample frames
/// every 128 samples and each is windowed and transformed. A per-bin estimate
/// of the background noise floor is tracked continuously. Each bin is then
/// multiplied by a Wiener gain — `SNR / (SNR + k)` — over a decision-directed
/// estimate of that bin's signal-to-noise ratio, with `k` the over-subtraction
/// factor the user's amount sets and a floor under the result so a suppressed
/// bin fades rather than vanishes. The frames are windowed again and
/// overlap-added back.
///
/// **It is not a gate, and the difference is the point.** Nothing here
/// compares a level with a threshold and decides between "signal" and
/// "silence": every bin of every frame keeps the fraction of itself that its
/// own SNR says is signal, so a quiet passage keeps its content and a steady
/// hiss is attenuated *underneath* speech rather than only between words. What
/// it cannot do is remove a noise that is not stationary — a door slam, a
/// cough — because nothing distinguishes those from the material.
///
/// **The noise estimate is continuous minimum tracking** (Doblinger's
/// recursive-minimum variant of Martin's minimum statistics): the smoothed
/// power in each bin is followed by a value that falls to it instantly and
/// rises back only slowly, so it settles on the floor the bin returns to
/// between sounds. That needs no noise print from the user and no silence at
/// the head of the clip. Its known cost is that a bin which is never quiet —
/// a long held note — is eventually read as noise; `minimumRise` is set for
/// that case and the decision-directed SNR carries the rest.
///
/// **Latency.** An STFT cannot see a sample's neighbours before they arrive,
/// so the output lags the input by one analysis window: 512 samples, 10.7 ms
/// at 48 kHz. Measured, not assumed: a tap's process callback cannot read
/// ahead — a second `MTAudioProcessingTapGetSourceAudio` inside one callback
/// returns the SAME audio again rather than the next block, so priming a
/// look-ahead is impossible. 10.7 ms is far inside every A/V sync tolerance
/// and applies only to a track some clip of which asks for noise reduction;
/// `AudioTap` keeps the stage running for the whole track once any clip on it
/// does, so the delay never changes at a cut.
final class AudioNoiseReductionStage {
    /// Analysis window, a power of two for `vDSP`'s radix-2 FFT.
    static let window = 512
    /// Hop: 75 % overlap, which is what a √Hann pair needs to add back up to
    /// a constant and is fine enough that a modified bin does not smear.
    static let hop = 128

    private let log2n: vDSP_Length
    private let setup: FFTSetup
    private let half: Int

    /// √Hann, used for BOTH analysis and synthesis (Griffin–Lim): windowing
    /// twice is what keeps a per-bin gain change from clicking at the frame
    /// edges.
    private let windowCurve: UnsafeMutablePointer<Float>
    /// Everything below is allocated once and reused every frame.
    private let history: UnsafeMutablePointer<Float>      // last `window` inputs
    private let staging: UnsafeMutablePointer<Float>      // this hop's inputs
    private let frame: UnsafeMutablePointer<Float>
    private let real: UnsafeMutablePointer<Float>
    private let imaginary: UnsafeMutablePointer<Float>
    private let power: UnsafeMutablePointer<Float>        // half + 1
    private let smoothed: UnsafeMutablePointer<Float>     // half + 1
    private let minimum: UnsafeMutablePointer<Float>      // half + 1
    private let binGain: UnsafeMutablePointer<Float>      // half + 1
    /// Last frame's estimate of the CLEAN power per bin, which is what makes
    /// the a priori SNR below a decision-directed one rather than a raw
    /// per-frame ratio.
    private let cleaned: UnsafeMutablePointer<Float>      // half + 1
    private let overlap: UnsafeMutablePointer<Float>      // window
    /// The finished samples waiting to be handed back, as a plain FIFO with a
    /// read and a write index. It never holds more than two hops, and it is
    /// compacted on a push rather than shifted on a pop — a `memmove` per
    /// SAMPLE is what a naive queue costs here, and this runs on the audio
    /// thread.
    private let output: UnsafeMutablePointer<Float>       // window + hop
    private var outputHead = 0
    private var outputTail = 0
    private var stagedCount = 0
    /// False until the first frame has been analysed. The tracker starts at
    /// that frame's own power rather than at zero: from zero it would take
    /// its whole rise constant to charge up to the noise floor, and until it
    /// did every bin would look like signal and nothing would be removed.
    private var primed = false
    /// The forward/inverse round trip's scale, times the overlap-add
    /// normalisation. Both are constants of the window and the hop, so they
    /// are folded into one multiply.
    private let scale: Float

    /// Smoothing of the per-bin power before the minimum tracker sees it.
    private let powerSmoothing: Float = 0.7
    /// How fast the tracked minimum may rise back — the one number that
    /// decides whether a held note is mistaken for the room.
    ///
    /// The tracker FALLS instantly and rises at this rate, so an
    /// overestimate corrects itself within a few frames of quiet while an
    /// underestimate persists. That asymmetry says to be slow: 0.9999 per hop
    /// is about 27 s at 48 kHz. Measured on a one-second 700 Hz tone buried
    /// in white noise, 0.998 (1.4 s) took 12 dB off the tone and 0.9995 (5 s)
    /// took 10 dB, because the tracker climbed to the tone and the filter
    /// then read it as the floor; at 0.9999 the tone comes through within
    /// half a dB and the noise-only stretches still lose 13.
    private let minimumRise: Float = 0.9999
    private let minimumBias: Float = 0.96
    /// The tracked minimum reads low, because it is a minimum; the usual
    /// compensation for the bias of that estimator.
    private let noiseBias: Float = 1.5
    /// How much of the a priori SNR is carried from the previous frame's
    /// clean estimate. 0.98 is Ephraim and Malah's own figure, and it is what
    /// stops the gain from chattering bin by bin — the chatter IS musical
    /// noise.
    private let decisionDirected: Float = 0.98

    init?() {
        var n = 1
        var bits: vDSP_Length = 0
        while n < Self.window {
            n <<= 1
            bits += 1
        }
        guard n == Self.window, let setup = vDSP_create_fftsetup(bits, FFTRadix(kFFTRadix2))
        else { return nil }
        self.setup = setup
        log2n = bits
        half = Self.window / 2

        windowCurve = .allocate(capacity: Self.window)
        history = .allocate(capacity: Self.window)
        staging = .allocate(capacity: Self.hop)
        frame = .allocate(capacity: Self.window)
        real = .allocate(capacity: half)
        imaginary = .allocate(capacity: half)
        power = .allocate(capacity: half + 1)
        smoothed = .allocate(capacity: half + 1)
        minimum = .allocate(capacity: half + 1)
        binGain = .allocate(capacity: half + 1)
        cleaned = .allocate(capacity: half + 1)
        overlap = .allocate(capacity: Self.window)
        output = .allocate(capacity: Self.window + Self.hop)

        history.initialize(repeating: 0, count: Self.window)
        staging.initialize(repeating: 0, count: Self.hop)
        frame.initialize(repeating: 0, count: Self.window)
        real.initialize(repeating: 0, count: half)
        imaginary.initialize(repeating: 0, count: half)
        power.initialize(repeating: 0, count: half + 1)
        smoothed.initialize(repeating: 0, count: half + 1)
        minimum.initialize(repeating: 0, count: half + 1)
        binGain.initialize(repeating: 1, count: half + 1)
        cleaned.initialize(repeating: 0, count: half + 1)
        overlap.initialize(repeating: 0, count: Self.window)
        output.initialize(repeating: 0, count: Self.window + Self.hop)

        // Periodic Hann, square-rooted: `hann` itself is what the analysis and
        // synthesis windows multiply to, and 75 % overlap makes those sum to a
        // constant. The constant is computed rather than quoted, so the round
        // trip is unity whatever the window and hop become.
        var overlapSum: Float = 0
        for index in 0..<Self.window {
            let hann = 0.5 - 0.5 * cos(2 * Float.pi * Float(index) / Float(Self.window))
            windowCurve[index] = sqrt(max(hann, 0))
        }
        for step in stride(from: 0, to: Self.window, by: Self.hop) {
            let sample = windowCurve[step]
            overlapSum += sample * sample
        }
        // `vDSP_fft_zrip` returns a spectrum scaled by 2, and the inverse does
        // not undo the transform's own length, so a round trip needs 1/(2·N).
        scale = 1 / (2 * Float(Self.window) * max(overlapSum, .leastNormalMagnitude))
        resetState()
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AudioNoiseReductionStage does not support NSCoder")
    }

    deinit {
        vDSP_destroy_fftsetup(setup)
        windowCurve.deallocate()
        history.deallocate()
        staging.deallocate()
        frame.deallocate()
        real.deallocate()
        imaginary.deallocate()
        power.deallocate()
        smoothed.deallocate()
        minimum.deallocate()
        binGain.deallocate()
        cleaned.deallocate()
        overlap.deallocate()
        output.deallocate()
    }

    /// Empties the pipeline and re-primes the delay line.
    ///
    /// The queue starts holding ONE HOP of silence, not one window. Frame `k`
    /// finishes the hop of output that begins at input `(k + 1)·hop − window`,
    /// so the overlap-add itself already delays by `window − hop`; priming the
    /// queue with one more hop makes the total exactly `window` and — checked
    /// against every arrival pattern, not just the tidy one — leaves the queue
    /// unable to run dry between hops.
    func reset() { resetState() }

    private func resetState() {
        history.update(repeating: 0, count: Self.window)
        staging.update(repeating: 0, count: Self.hop)
        overlap.update(repeating: 0, count: Self.window)
        output.update(repeating: 0, count: Self.window + Self.hop)
        smoothed.update(repeating: 0, count: half + 1)
        minimum.update(repeating: 0, count: half + 1)
        cleaned.update(repeating: 0, count: half + 1)
        primed = false
        outputHead = 0
        outputTail = Self.hop
        stagedCount = 0
    }

    /// Filters `frames` samples in place.
    ///
    /// `amount` is the clip's `noise_reduction`, read fresh on every call
    /// because the clip under the playhead changes at every cut. At 0 the
    /// gain floor is 1, every bin's gain is 1, and the stage is an exact
    /// (float-precision) delay rather than a filter — which is what keeps a
    /// track that mixes reduced and unreduced clips from changing its latency
    /// halfway through.
    func process(_ data: UnsafeMutablePointer<Float>, frames: Int, amount: Double) {
        guard frames > 0 else { return }
        let clamped = Float(min(max(amount.isFinite ? amount : 0, 0), 1))
        // Over-subtraction: 1 removes exactly the estimate, 4 removes four
        // times it. The floor is what is left of a bin the subtraction would
        // otherwise empty; at amount 0 it is 1, which makes every gain 1.
        let overSubtraction = 1 + 3 * clamped
        let floorGain = 1 - clamped

        for index in 0..<frames {
            // Samples are staged a hop at a time and the history is shifted
            // once per hop, not once per sample: the window is a plain
            // in-order buffer (which is what `vDSP_vmul` wants) and the price
            // of that is 384 floats moved per 128 samples rather than 511 per
            // one. A ring buffer would need no move at all and would cost an
            // unwrap on every read of every frame instead — the wrong trade at
            // 75 % overlap.
            staging[stagedCount] = data[index]
            stagedCount += 1
            if stagedCount == Self.hop {
                stagedCount = 0
                memmove(
                    history, history + Self.hop,
                    (Self.window - Self.hop) * MemoryLayout<Float>.size)
                (history + Self.window - Self.hop).update(from: staging, count: Self.hop)
                processFrame(overSubtraction: overSubtraction, floorGain: floorGain)
            }
            data[index] = popOutput()
        }
    }

    /// One analysis/synthesis frame over the newest `window` samples.
    private func processFrame(overSubtraction: Float, floorGain: Float) {
        vDSP_vmul(history, 1, windowCurve, 1, frame, 1, vDSP_Length(Self.window))

        var split = DSPSplitComplex(realp: real, imagp: imaginary)
        frame.withMemoryRebound(to: DSPComplex.self, capacity: half) { pointer in
            vDSP_ctoz(pointer, 2, &split, 1, vDSP_Length(half))
        }
        vDSP_fft_zrip(setup, &split, 1, log2n, FFTDirection(kFFTDirection_Forward))

        // `vDSP_fft_zrip` packs DC in real[0] and Nyquist in imaginary[0];
        // both are real, so they get their own slots at either end of the
        // power array rather than being treated as a complex pair.
        power[0] = real[0] * real[0]
        power[half] = imaginary[0] * imaginary[0]
        for bin in 1..<half {
            power[bin] = real[bin] * real[bin] + imaginary[bin] * imaginary[bin]
        }

        for bin in 0...half {
            let current = power[bin]
            let smooth =
                primed ? powerSmoothing * smoothed[bin] + (1 - powerSmoothing) * current : current
            if !primed {
                minimum[bin] = smooth
            } else if minimum[bin] < smooth {
                // Rise slowly, and only as fast as the smoothed power itself
                // is rising — Doblinger's recursion, which is what stops a
                // long vowel from dragging the floor up with it.
                minimum[bin] =
                    minimumRise * minimum[bin]
                    + ((1 - minimumRise) / (1 - minimumBias))
                    * (smooth - minimumBias * smoothed[bin])
            } else {
                minimum[bin] = smooth
            }
            smoothed[bin] = smooth

            // The gain is a Wiener filter over the a priori SNR, and the a
            // priori SNR is the decision-directed estimate: mostly what last
            // frame's clean output says this bin holds, corrected by what
            // this frame's power says. Subtracting the noise estimate from
            // the power directly (the textbook subtractor) makes the gain
            // jump with the periodogram's own variance, which is heard as
            // bins winking in and out; this does not.
            let noise = max(max(minimum[bin], 0) * noiseBias, .leastNormalMagnitude)
            let posterior = current / noise
            let prior = max(
                decisionDirected * cleaned[bin] / noise
                    + (1 - decisionDirected) * max(posterior - 1, 0),
                1e-6)
            // `overSubtraction` in the denominator generalises the filter: 1
            // is the plain Wiener gain, 4 removes four times as much for the
            // same SNR. The floor is what a bin keeps when the filter would
            // otherwise empty it — at amount 0 the floor is 1 and the whole
            // rule collapses to a no-op.
            let gain = max(floorGain, prior / (prior + overSubtraction))
            binGain[bin] = gain
            cleaned[bin] = gain * gain * current
        }
        primed = true

        real[0] *= binGain[0]
        imaginary[0] *= binGain[half]
        for bin in 1..<half {
            real[bin] *= binGain[bin]
            imaginary[bin] *= binGain[bin]
        }

        vDSP_fft_zrip(setup, &split, 1, log2n, FFTDirection(kFFTDirection_Inverse))
        frame.withMemoryRebound(to: DSPComplex.self, capacity: half) { pointer in
            vDSP_ztoc(&split, 1, pointer, 2, vDSP_Length(half))
        }
        var factor = scale
        vDSP_vsmul(frame, 1, &factor, frame, 1, vDSP_Length(Self.window))
        vDSP_vmul(frame, 1, windowCurve, 1, frame, 1, vDSP_Length(Self.window))
        vDSP_vadd(overlap, 1, frame, 1, overlap, 1, vDSP_Length(Self.window))

        // The first `hop` samples of the accumulator have now been summed by
        // every frame that covers them, so they are finished: they go to the
        // output queue and the accumulator slides.
        pushOutput(overlap, count: Self.hop)
        memmove(overlap, overlap + Self.hop, (Self.window - Self.hop) * MemoryLayout<Float>.size)
        (overlap + Self.window - Self.hop).update(repeating: 0, count: Self.hop)
    }

    /// Appends finished samples, compacting the queue first when the tail has
    /// run out of room. The queue holds at most two hops, so the capacity of
    /// `window + hop` can never actually be exceeded; the `take` clamp is
    /// there so that a future window/hop pair which broke that invariant would
    /// drop samples rather than write off the end.
    private func pushOutput(_ source: UnsafeMutablePointer<Float>, count: Int) {
        let capacity = Self.window + Self.hop
        if outputTail + count > capacity {
            let held = outputTail - outputHead
            if held > 0 { memmove(output, output + outputHead, held * MemoryLayout<Float>.size) }
            outputHead = 0
            outputTail = held
        }
        let take = min(count, capacity - outputTail)
        guard take > 0 else { return }
        (output + outputTail).update(from: source, count: take)
        outputTail += take
    }

    private func popOutput() -> Float {
        guard outputHead < outputTail else { return 0 }
        let value = output[outputHead]
        outputHead += 1
        return value
    }
}

// MARK: - The chain

/// One composition audio track's effect chain: noise reduction, then the
/// compressor, then the Mix stage — the mono fold, then the pan, then the
/// fold an enclosing NEST clip asked for.
///
/// **That order is the order a channel strip has**, and each step is there
/// because of the one before it. Cleaning first means the compressor is not
/// asked to make a decision about a level the hiss is holding up — a
/// compressor in front of a noise reducer pumps the noise floor audibly.
/// Panning last means the reduction is computed on the signal as it was
/// recorded, not on a channel the pan has already leaned.
///
/// **The fold is at the head of the Mix stage, after the compressor and
/// before the pan.** After the pan it would undo it (see `AudioPanLaw`);
/// before the noise reducer it would hand both reducers identical input,
/// which invites the false optimisation of running one and copying — and a
/// stage that stopped being fed would click the moment mono came off at a
/// cut, because mono is a per-CLIP setting and the reducers are stateful.
/// Where it is, it also makes `AudioPane`'s Mix section — which holds `mono`
/// and `pan`, in that order — literally the DSP order, which that pane
/// already claims for the other three sections.
///
/// **A NEST clip's fold is the one thing that runs after the pan**, and it is
/// not an exception to the paragraph above: it belongs to a different clip.
/// It stands for a fold of the whole nest's MIX, and a mix is a sum, so
/// folding each contributor at the very end of its own chain sums to exactly
/// the same samples (`AudioClipDSP.enclosingMono` argues it). Running it at
/// the head with the clip's own would fold BEFORE the inner clip's pan and
/// leave a hard-panned clip hard-panned inside a nest the user folded.
///
/// The clip's own volume, its fades and any ducking are NOT here: `audio.rs`
/// folds those into the plan's envelope and `AVMutableAudioMixInputParameters`
/// applies them as volume ramps, which — measured — happen downstream of a
/// tap created with `kMTAudioProcessingTapCreationFlag_PreEffects`. So the
/// full order the samples actually see is
/// noise reduction → compressor → the clip's fold → pan → an enclosing nest's
/// fold → volume/fades/ducking, which puts the compressor before the fader
/// exactly as an insert should be.
final class AudioDSPChain {
    let channelCount: Int
    private let compressor: AudioCompressorStage
    /// One per channel, or nil when no clip on this track asks for noise
    /// reduction — in which case the track has no added latency at all.
    private let reducers: [AudioNoiseReductionStage]?

    /// `usesNoiseReduction` is decided for the WHOLE track when the
    /// composition is built, not per buffer: the stage adds a fixed delay, and
    /// switching it in and out at a cut would make the track jump backwards
    /// and forwards by 10 ms.
    init(channelCount: Int, sampleRate: Double, maxFrames: Int, usesNoiseReduction: Bool) {
        self.channelCount = max(0, channelCount)
        compressor = AudioCompressorStage(sampleRate: sampleRate, maxFrames: maxFrames)
        if usesNoiseReduction, self.channelCount > 0 {
            // All channels or none: a track whose left channel was filtered
            // and whose right was not would be delayed on one side, which is
            // worse than not filtering at all. `vDSP_create_fftsetup` is the
            // only thing that can fail here, and if it does the clip plays
            // and exports with its pan and compressor and without its noise
            // reduction, rather than not playing.
            let stages = (0..<self.channelCount).compactMap { _ in AudioNoiseReductionStage() }
            reducers = stages.count == self.channelCount ? stages : nil
        } else {
            reducers = nil
        }
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AudioDSPChain does not support NSCoder")
    }

    /// Drops every bit of carried state — the compressor's envelope, the
    /// reducers' delay lines and noise estimates. `AudioTap` calls this when
    /// the stream restarts, so a seek does not play the previous position's
    /// tail.
    func reset() {
        compressor.reset()
        reducers?.forEach { $0.reset() }
    }

    /// Runs the chain in place over one buffer.
    ///
    /// `params` is the clip under this buffer's timestamp. It changes at every
    /// cut on the track; the stages carry their state across the change, which
    /// is what a track insert does.
    func process(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, frames: Int,
        params: AudioClipDSP
    ) {
        let count = min(channels.count, channelCount)
        guard frames > 0, count > 0 else { return }

        if let reducers = reducers {
            for channel in 0..<min(count, reducers.count) {
                guard let data = channels[channel] else { continue }
                reducers[channel].process(data, frames: frames, amount: params.noiseReduction)
            }
        }

        compressor.process(channels, count: count, frames: frames, settings: params.compressor)

        // The head of the Mix stage. The branch is not entered at all for a
        // clip that does not ask for mono — not multiplied by one, not folded
        // with a weight of zero — which is what makes an untouched track's
        // samples bit-identical to the build before this landed, by
        // construction rather than by argument.
        if params.mono, count >= 2 { fold(channels, count: count, frames: frames) }

        pan(channels, count: count, frames: frames, position: params.pan)

        // The tail: the fold a nest clip ABOVE this one asked for, after
        // everything this clip does to its own channels, which is what makes
        // the sum of the folded contributors the fold of the sum.
        if params.enclosingMono, count >= 2 { fold(channels, count: count, frames: frames) }
    }

    /// The pan, in place. Its own method only so the tail fold above it is
    /// reachable: every early return here used to end `process`.
    ///
    /// Pan needs somewhere to pan TO. A mono composition track is prepared
    /// with one channel and is widened to stereo downstream of the tap, so
    /// there is nothing here to lean; the pan is silently inaudible on such a
    /// clip rather than turning into a volume change, which is what applying
    /// half a pan law to a single channel would be.
    private func pan(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int, position: Double
    ) {
        guard count >= 2 else { return }
        let gains = AudioPanLaw.gains(position)
        guard gains.left != 1 || gains.right != 1 else { return }
        var left = gains.left
        var right = gains.right
        if let data = channels[0] { vDSP_vsmul(data, 1, &left, data, 1, vDSP_Length(frames)) }
        if let data = channels[1] { vDSP_vsmul(data, 1, &right, data, 1, vDSP_Length(frames)) }
    }

    /// Averages EVERY channel and writes the average to all of them.
    ///
    /// **Every channel, not L and R.** `prepare` is handed the COMPOSITION
    /// track's channel count, so a 5.1 source gives 6; folding only channels 0
    /// and 1 would leave four untouched and produce something that is neither
    /// mono nor the original. At two channels this is exactly (L+R)/2.
    ///
    /// Allocation-free and stateless: `count` linear passes plus `count − 1`
    /// copies over at most `maxFrames` floats, which is two orders of
    /// magnitude under one noise-reduction frame. The accumulator is the first
    /// channel that actually has a buffer, and the divisor counts only the
    /// channels that contributed — a null buffer must not quietly attenuate
    /// the rest.
    private func fold(
        _ channels: UnsafeMutableBufferPointer<UnsafeMutablePointer<Float>?>, count: Int,
        frames: Int
    ) {
        var accumulator: UnsafeMutablePointer<Float>?
        var summed = 0
        for channel in 0..<count {
            guard let data = channels[channel] else { continue }
            summed += 1
            guard let into = accumulator else {
                accumulator = data
                continue
            }
            vDSP_vadd(into, 1, data, 1, into, 1, vDSP_Length(frames))
        }
        guard let into = accumulator, summed >= 2 else { return }
        var scale = 1 / Float(summed)
        vDSP_vsmul(into, 1, &scale, into, 1, vDSP_Length(frames))
        for channel in 0..<count {
            guard let data = channels[channel], data != into else { continue }
            data.update(from: into, count: frames)
        }
    }
}

import AVFoundation
import Foundation

/// Where `AudioDSP`'s effects meet AVFoundation: the parameters, the schedule
/// that says which clip a buffer belongs to, and the `MTAudioProcessingTap`
/// that carries both into the audio path.
///
/// **One tap serves the preview AND the export, and that is measured.** The
/// recon this slice started from warned that `audioTapProcessor` is an
/// AVPlayer-time feature and that a tap would give a preview that sounds
/// processed and a file that does not — the one failure spec §7's whole design
/// exists to prevent. That was true of `AVAssetExportSession`, which the
/// export no longer uses. It is NOT true of the reader/writer pipeline that
/// replaced it: with a tap on the input parameters and the same
/// `AVMutableAudioMix` handed to `AVAssetReaderAudioMixOutput`, the process
/// callback ran 188 times over a two-second composition and a tap that
/// silenced its buffers produced a silent file. Two further measurements make
/// it usable:
///
///  - **Each track's tap sees only its own track, before the mix.** A tap that
///    silenced composition track 1 of two produced a mix byte-identical to
///    track 2 read alone. So per-clip settings survive the A/B track
///    assignment (§7.2), which is the thing a post-mix filter could not do.
///  - **A pass-through tap is bit-transparent.** Reading the same composition
///    with no mix at all and with a tap that pulls its source audio and
///    returns it unchanged gave identical bytes, and adding a volume ramp
///    alongside changed nothing either. The tap is not a lossy insert; the
///    reason a track with nothing to do gets none is CPU and clarity, not
///    fidelity.
///
/// **The clip's other audio properties are NOT here.** Volume, the fades and
/// ducking are already one envelope per track in the plan (`audio.rs`), played
/// back as volume ramps. Those apply downstream of a tap created with
/// `kMTAudioProcessingTapCreationFlag_PreEffects`, so the compressor sees the
/// clip at its recorded level rather than at the level the fader is passing —
/// an insert before the fader, which is where a compressor belongs. What IS
/// here is everything the plan cannot carry: pan, the mono fold, the
/// compressor and noise reduction.
///
/// **The tap also meters, and it is the only thing that can.** A meter wants
/// the mix level, which would be a PostEffects tap — but
/// `AVMutableAudioMixInputParameters` has exactly one `audioTapProcessor` and
/// the two flags are exclusive, so a track carrying this one cannot carry a
/// second, and moving this one to PostEffects would put the compressor behind
/// the fader and change how every project with a compressor sounds. So a
/// METERING build (playback only, `CompositionBuilder.build(metering:)`) hands
/// every audio track a `LevelMeterSink` — including the tracks that ask for no
/// processing at all and would otherwise carry no tap, or the meter would
/// light only on tracks that happen to have a compressor — and the reader
/// multiplies by the plan's envelope to get the post-fader number.
/// `LevelMeter.swift` argues the whole of that; the part that belongs here is
/// that metering never reaches an EXPORT, so every export keeps exactly the
/// audio path it had.

// MARK: - The schedule

/// One clip's stretch of a composition audio track, in composition ticks.
///
/// Composition time equals timeline time on these tracks — `CompositionBuilder`
/// fills them behind a cursor precisely so that stays true through speed
/// changes — so the plan's own `start` and `duration` are what a buffer's
/// timestamp is compared against.
struct AudioDSPSpan: Equatable {
    let start: Ticks
    /// Exclusive.
    let end: Ticks
    let dsp: AudioClipDSP
}

/// What one composition audio track's tap needs to know, decided once when
/// the composition is built.
struct AudioTrackDSP: Equatable {
    let spans: [AudioDSPSpan]
    /// Whether any clip on this track asks for anything at all. False means no
    /// tap is created, and the track's samples are exactly what the build
    /// before this file existed produced.
    let isActive: Bool
    /// Whether the noise reducer runs for the WHOLE track. It is all or
    /// nothing per track by design: the stage delays by 512 samples, and
    /// switching it in at a cut would jump the track 10 ms backwards
    /// mid-programme.
    let usesNoiseReduction: Bool

    init(segments: [PlanSegment], parameters: AudioDSPParameters) {
        var spans: [AudioDSPSpan] = []
        spans.reserveCapacity(segments.count)
        for segment in segments where segment.duration > 0 {
            let dsp = parameters.dsp(for: segment.clip)
            guard !dsp.isInert else { continue }
            spans.append(
                AudioDSPSpan(
                    start: segment.start, end: segment.start + segment.duration, dsp: dsp))
        }
        self.spans = spans
        isActive = !spans.isEmpty
        usesNoiseReduction = spans.contains { $0.dsp.noiseReduction > 0 }
    }

    private init() {
        spans = []
        isActive = false
        usesNoiseReduction = false
    }

    /// A track that asks for no processing at all. What a METERING-only tap is
    /// built with: it still has to fetch and hand on its source audio, and it
    /// still has to measure it, but no chain is built for it and no sample is
    /// touched.
    static let inert = AudioTrackDSP()
}

// MARK: - Parameters, and where they come from

/// Every clip's sample-level audio settings, keyed by clip id.
///
/// Only the clips that ask for something are in the dictionary: an empty one
/// means the whole project needs no tap anywhere, which is the state every
/// project made before this feature existed is in.
struct AudioDSPParameters: Equatable {
    private let clips: [UInt32: AudioClipDSP]

    static let empty = AudioDSPParameters(clips: [:])

    private init(clips: [UInt32: AudioClipDSP]) {
        self.clips = clips
    }

    /// Reads the settings off a project snapshot, nests included — a nested
    /// clip gets its own composition audio track exactly as a top-level one
    /// does, and `Project.clips` and `Nest.clips` share one id space, so one
    /// flat dictionary covers both.
    ///
    /// **A nest CLIP is not in the dictionary, and its own `mono` is carried
    /// down instead.** The plan replaced a nest with the clips inside it
    /// (`nest.rs`), so an audio segment always names the INNERMOST clip and
    /// nothing could ever look a nest clip's entry up — a `mono` written on
    /// one would be accepted by the core, kept by the checkbox, saved with
    /// the project and silently fold nothing, which is what it did until this
    /// walk existed. So every clip inside a folded nest is marked
    /// `enclosingMono` and folds at the tail of its own chain, which sums to
    /// exactly the fold of the nest's mix (`AudioClipDSP.enclosingMono`).
    /// A nest inside a folded nest is walked too: an outer fold applies to
    /// everything within, and folding twice is folding once.
    ///
    /// **The nest clip's other three do NOT travel, and two of them cannot.**
    /// The compressor and the noise reducer are not linear, so running either
    /// on each contributor is a different sound from running it on the mix —
    /// bus compression is the whole reason a bus has a compressor — and the
    /// reducer would also delay each inner track by its own 512 samples. Pan
    /// is linear and could ride down the same walk, but two pans do not
    /// compose into one number (`AudioClipDSP` carries one `pan`, and the
    /// product of two constant-power pairs is no single position), and
    /// turning it on would change how projects that already carry a nest pan
    /// sound — the decision M3 recorded for `mono` itself, which phase 5
    /// took deliberately and one at a time. So a nest clip's pan, compressor
    /// and noise reduction reach nothing, exactly as they did in M3.
    ///
    /// **One limit the id space imposes:** two nest clips may show the SAME
    /// nest, and the dictionary is keyed by clip id while the plan's segments
    /// carry no instance path, so a fold asked for by one of them folds both.
    /// Folding is the choice that makes the control do what it says on the
    /// clip that asked; the alternative — fold only when every nest clip
    /// showing the nest agrees — makes the checkbox do nothing at all.
    ///
    /// **Base properties only, never through actions.** A clip's numbers can
    /// be animated (`actions.rs` lerps any of them), and none of the four is
    /// read at the animated value: the plan carries no per-tick audio, the
    /// tap would have to evaluate the action itself, and evaluation is Rust's
    /// job. Ducking already works this way — `audio.rs`'s `duckers()` reads
    /// base props and says so — so this is the established answer rather than
    /// a new exception. An action that animates `pan` moves nothing.
    init(snapshot: ProjectSnapshot) {
        var clips: [UInt32: AudioClipDSP] = [:]
        func collect(_ list: [ClipSnapshot]) {
            for clip in list {
                // A nest clip's own entry could never be looked up: its id
                // names no audio segment. `fold` below is where its `mono`
                // goes instead.
                guard clip.source.nestID == nil, let audio = clip.audio else { continue }
                let dsp = AudioClipDSP(
                    pan: audio.pan,
                    compressor: audio.compressor.map {
                        AudioCompressorSettings(
                            thresholdDB: $0.thresholdDb, ratio: $0.ratio,
                            attackSeconds: AudioDSPParameters.seconds($0.attack),
                            releaseSeconds: AudioDSPParameters.seconds($0.release),
                            makeupDB: $0.makeupDb)
                    },
                    noiseReduction: audio.noiseReduction,
                    mono: audio.mono)
                guard !dsp.isInert else { continue }
                clips[clip.id] = dsp
            }
        }
        collect(snapshot.clips)
        for nest in snapshot.nests { collect(nest.clips) }

        // Marks everything `nestID` stands for, however deep. Bounded by the
        // core's `MAX_NEST_DEPTH` (8, `format.rs`) rather than trusted to
        // terminate: `validate` refuses a deeper — and so a circular — nest,
        // but this walk reads a decoded snapshot and a walk that can be
        // handed a cycle is a walk that must be bounded.
        func fold(contentsOf nestID: UInt32, depth: Int) {
            guard depth <= AudioDSPParameters.nestDepthCap, let nest = snapshot.nest(nestID)
            else { return }
            for clip in nest.clips {
                if let inner = clip.source.nestID {
                    fold(contentsOf: inner, depth: depth + 1)
                    continue
                }
                // Every clip inside, not only the ones carrying audio props:
                // which of them gets an audio segment is `evaluate.rs`'s rule
                // (the media has sound, and `enabled.audio` holds all the way
                // up), not one Swift may restate, and an entry the tap never
                // looks up costs a dictionary slot and nothing else.
                var dsp = clips[clip.id] ?? .inert
                dsp.enclosingMono = true
                clips[clip.id] = dsp
            }
        }
        func foldMonoNests(_ list: [ClipSnapshot]) {
            for clip in list where clip.audio?.mono == true {
                guard let nestID = clip.source.nestID else { continue }
                fold(contentsOf: nestID, depth: 1)
            }
        }
        foldMonoNests(snapshot.clips)
        for nest in snapshot.nests { foldMonoNests(nest.clips) }
        self.clips = clips
    }

    /// `format.rs`'s `MAX_NEST_DEPTH`. Duplicated rather than bridged: the
    /// FFI carries no constant for it, and a walk one level shallower than
    /// the core allows would silently stop folding, so the number is written
    /// where a reader comparing the two files can see it.
    private static let nestDepthCap = 8

    /// Ticks → seconds, the one place the compressor's two times cross that
    /// boundary.
    private static func seconds(_ ticks: Ticks) -> Double {
        Double(max(ticks, 0)) / Double(ReelTime.perSecond)
    }

    func dsp(for clip: UInt32) -> AudioClipDSP { clips[clip] ?? .inert }

    var isEmpty: Bool { clips.isEmpty }
}

/// The process-wide place `CompositionBuilder` finds a document's audio DSP
/// parameters, keyed by the same `RecipeSource` slot the compositor reads
/// recipes under.
///
/// **Why this is not simply read off the project.** The parameters are per
/// clip, and `CompositionBuilder.build` is handed the composition PLAN, not
/// the project: the plan is `plan.rs`'s structural description and carries
/// no audio properties beyond the envelope and the time-pitch algorithm. Both
/// callers do publish the project first — `Playback.update` and
/// `Exporter.export` each call `RecipeSource.shared.set` before building — but
/// `RecipeSource` exposes only `recipe(for:at:)`, and a frame recipe has no
/// audio in it. So this mirror exists beside it, published from `Playback`.
///
/// **Why a key with no entry still gets the right answer.** An export mints a
/// FRESH `RecipeSource` key (`Exporter.swift`: "NOT the document's", so a
/// frame already queued cannot be composed from a project the user changed
/// mid-write), and nothing publishes a document's parameters under that new
/// key. What every such caller DOES publish under it is the project handle
/// itself, so the lookup reads that handle back through
/// `RecipeSource.project(for:)` and derives the parameters from its snapshot —
/// the same pure `init(snapshot:)` `Playback` publishes through, applied to
/// exactly the project being built.
///
/// It was once a scan for the published document whose plan JSON matched the
/// one being built. That is a guess, and it guessed wrong the moment two
/// documents were open with byte-identical composition plans: it could not
/// tell them apart, so it returned nothing and every export ran with the DSP
/// silently switched off. Measured, not theorised — two projects each holding
/// one clip of the same file was enough. A key names one composition; ask it
/// rather than the population.
final class AudioDSPSource {
    static let shared = AudioDSPSource()

    private let lock = NSLock()
    private var entries: [Int: AudioDSPParameters] = [:]

    private init() {}

    /// Publishes a document's parameters. Main thread, after every edit.
    ///
    /// `Playback` publishes here so the player never pays for a decode on a
    /// scrub; the derivation in `parameters(for:)` is the same function, so
    /// the two can never disagree about what a project asks for.
    func publish(_ parameters: AudioDSPParameters, for key: Int) {
        lock.lock()
        defer { lock.unlock() }
        entries[key] = parameters
    }

    /// Drops a document's slot, the way `RecipeSource.unregister` does.
    func unpublish(_ key: Int) {
        lock.lock()
        defer { lock.unlock() }
        entries.removeValue(forKey: key)
    }

    /// The parameters for the composition being built under `key`: the
    /// published entry, or — for a key minted for one export or one rendered
    /// frame — derived from the project that key was registered with.
    ///
    /// Never guesses. A key with no entry and no published project is a
    /// composition nothing claims, and that gets `.empty`: an unprocessed
    /// export, not a wrongly processed one.
    func parameters(for key: Int) -> AudioDSPParameters {
        lock.lock()
        let published = entries[key]
        lock.unlock()
        if let published = published { return published }
        guard let project = RecipeSource.shared.project(for: key) else { return .empty }
        return AudioDSPParameters(snapshot: project.snapshot)
    }
}

// MARK: - The tap

/// One tap's state: what it was built with, and everything it carries between
/// buffers.
///
/// Held by the tap through `MTAudioProcessingTapGetStorage`, retained on
/// creation and released in the finalize callback — the tap is a CF object
/// owned by the `AVMutableAudioMixInputParameters` it is set on, and this
/// object's life is exactly the tap's.
final class AudioTapContext {
    private let track: AudioTrackDSP
    /// Where this track's levels are published, on a metering (playback)
    /// build; nil on every export and on every rendered frame. Written on the
    /// audio thread with two relaxed atomic stores and nothing else — see
    /// `LevelMeter.swift` for why it is not the `NSLock` the rest of the app
    /// publishes across threads with.
    private let meter: LevelMeterSink?
    private var chain: AudioDSPChain?
    /// The channel base pointers, refilled per buffer. A stored array so no
    /// allocation happens on the audio thread.
    private var channels: [UnsafeMutablePointer<Float>?] = []
    /// The rate `prepare` reported. Frames are turned into ticks with THIS
    /// and not with the timestamp's own timescale: the two happen to agree on
    /// both paths measured here, and only one of them is the contract.
    private var sampleRate: Ticks = 48000
    /// Where the last buffer ended, in composition ticks. Used when the tap
    /// reports no usable time — which the player's first callback after a
    /// start does — and to notice a seek.
    private var position: Ticks = 0

    /// How far a buffer's start may be from where the last one ended before it
    /// is treated as a seek rather than as the next block. A tenth of a second
    /// is far longer than any buffer this path delivers (4096 frames is 85 ms
    /// at 48 kHz) and far shorter than any jump a scrub makes.
    private static let seekTolerance: Ticks = ReelTime.perSecond / 10

    init(track: AudioTrackDSP, meter: LevelMeterSink?) {
        self.track = track
        self.meter = meter
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AudioTapContext does not support NSCoder")
    }

    /// `prepare`: the format is finally known, so the chain can size itself.
    /// Called again after every `unprepare`, so it replaces rather than adds.
    ///
    /// **The format is checked rather than assumed.** Both paths measured here
    /// hand a tap 32-bit float, non-interleaved, one `AudioBuffer` per channel
    /// — the format `AudioDSP` is written for. Nothing in the API promises
    /// that. If it is ever something else (interleaved, or fixed point) the
    /// chain is simply not built and the track passes through untouched:
    /// reading interleaved stereo as if it were one channel would apply the
    /// left gain to both and process half the buffer, which is a corrupted
    /// export rather than a missing feature. The METER is refused by the same
    /// guard and for the same reason — an interleaved buffer read as planar
    /// would meter half a channel — so a track in an unexpected format shows
    /// no level rather than a wrong one.
    ///
    /// `channels` being non-empty is what says the format was accepted; a
    /// metering-only track has no chain but still has that array, so
    /// everything that must not run in an unusable format is gated on it.
    func prepare(
        channelCount: Int, sampleRate: Double, maxFrames: Int,
        formatFlags: AudioFormatFlags, bitsPerChannel: UInt32
    ) {
        let float = formatFlags & kAudioFormatFlagIsFloat != 0
        let planar = formatFlags & kAudioFormatFlagIsNonInterleaved != 0
        guard float, planar, bitsPerChannel == 32, channelCount > 0 else {
            chain = nil
            channels = []
            meter?.clear()
            return
        }
        // No chain at all for a metering-only track: the compressor stage
        // alone allocates three buffers of `maxFrames`, and running it with no
        // settings would still be a multiply per sample per channel for a
        // track that asked for nothing.
        chain = track.isActive
            ? AudioDSPChain(
                channelCount: channelCount, sampleRate: sampleRate, maxFrames: maxFrames,
                usesNoiseReduction: track.usesNoiseReduction)
            : nil
        channels = Array(repeating: nil, count: channelCount)
        self.sampleRate = sampleRate >= 1 ? Ticks(sampleRate) : 48000
        position = 0
    }

    func unprepare() {
        chain = nil
        channels = []
        meter?.clear()
    }

    /// `process`: run the chain over one buffer of already-fetched audio.
    ///
    /// `time` is what `MTAudioProcessingTapGetSourceAudio` reported, which is
    /// invalid on the player's very first callback (measured) — hence the
    /// carried position.
    func process(
        _ bufferList: UnsafeMutablePointer<AudioBufferList>, frames: Int, time: CMTime,
        startOfStream: Bool
    ) {
        guard frames > 0, !channels.isEmpty else { return }
        let start = time.isNumeric ? CompositionBuilder.ticks(time) : position
        let list = UnsafeMutableAudioBufferListPointer(bufferList)
        let count = min(list.count, channels.count)
        guard count > 0 else { return }

        if let chain = chain {
            // A seek, a loop or a fresh stream: the compressor's envelope and
            // the reducer's delay line belong to the position we just left.
            if startOfStream || abs(start - position) > Self.seekTolerance {
                chain.reset()
            }

            // A buffer that straddles a cut is processed in runs, so a clip's
            // pan begins exactly at its own first sample rather than up to a
            // buffer early. The stages keep their state across the boundary —
            // they are track inserts, not per-clip effects.
            var offset = 0
            while offset < frames {
                let run = self.run(from: start + ticks(frames: offset), remaining: frames - offset)
                guard run.length > 0 else { break }
                for index in 0..<count {
                    channels[index] = list[index].mData?
                        .assumingMemoryBound(to: Float.self).advanced(by: offset)
                }
                channels.withUnsafeMutableBufferPointer { pointers in
                    chain.process(
                        UnsafeMutableBufferPointer(rebasing: pointers[0..<count]),
                        frames: run.length, params: run.dsp)
                }
                offset += run.length
            }
        }
        position = start + ticks(frames: frames)

        // AFTER the chain, and over the whole buffer rather than per run: what
        // the meter is asked for is the level this track hands the mix, and
        // the pan and the compressor have moved it. The run loop above left
        // `channels` pointing into the LAST run, so the base pointers are
        // written back before the sink reads them.
        guard let meter = meter else { return }
        for index in 0..<count {
            channels[index] = list[index].mData?.assumingMemoryBound(to: Float.self)
        }
        channels.withUnsafeMutableBufferPointer { pointers in
            meter.measure(
                UnsafeMutableBufferPointer(rebasing: pointers[0..<count]), count: count,
                frames: frames)
        }
    }

    private func ticks(frames: Int) -> Ticks {
        Ticks(frames) * ReelTime.perSecond / sampleRate
    }

    private func samples(_ ticks: Ticks) -> Int {
        let value = max(ticks, 0) * sampleRate / ReelTime.perSecond
        return value > Ticks(Int.max) ? Int.max : Int(value)
    }

    /// The longest run from `at` over which one clip's settings hold, and
    /// those settings. A gap between clips is a run of inert samples rather
    /// than a stop, so the silence between two panned clips stays silence.
    private func run(from at: Ticks, remaining: Int) -> (length: Int, dsp: AudioClipDSP) {
        guard let index = span(covering: at) else {
            // Not inside any span: run to whichever comes first, the next
            // span's start or the end of the buffer.
            guard let next = track.spans.first(where: { $0.start > at })?.start
            else { return (remaining, .inert) }
            return (min(remaining, max(1, samples(next - at))), .inert)
        }
        let span = track.spans[index]
        return (min(remaining, max(1, samples(span.end - at))), span.dsp)
    }

    /// Binary search rather than a carried cursor: a scrub jumps anywhere, and
    /// `log n` with no state beats `n` with state that a seek invalidates.
    private func span(covering at: Ticks) -> Int? {
        var low = 0
        var high = track.spans.count - 1
        while low <= high {
            let middle = (low + high) / 2
            let span = track.spans[middle]
            if at < span.start {
                high = middle - 1
            } else if at >= span.end {
                low = middle + 1
            } else {
                return middle
            }
        }
        return nil
    }
}

/// Builds the `MTAudioProcessingTap` for one composition audio track.
enum AudioTap {
    /// nil when the track needs no processing AND is not being metered, or
    /// when MediaToolbox refuses to make a tap — in which case the track plays
    /// and exports unprocessed and unmetered, which is the old behaviour
    /// rather than a failed build.
    ///
    /// A `meter` alone is enough to earn a tap: a metering build wants a level
    /// from every audio track, including the ones no clip has asked anything
    /// of. That tap builds no chain and touches no sample — it fetches its
    /// source audio, hands it straight on, and measures it.
    static func make(for track: AudioTrackDSP?, meter: LevelMeterSink?) -> MTAudioProcessingTap? {
        let track = track ?? .inert
        guard track.isActive || meter != nil else { return nil }
        // Retained here, released in `finalize` (or below, if no tap is made):
        // the tap owns the context and outlives every Swift reference to it.
        let context = Unmanaged.passRetained(
            AudioTapContext(track: track, meter: meter)).toOpaque()
        var callbacks = MTAudioProcessingTapCallbacks(
            version: kMTAudioProcessingTapCallbacksVersion_0,
            clientInfo: context,
            init: { _, clientInfo, storageOut in storageOut.pointee = clientInfo },
            finalize: { tap in
                Unmanaged<AudioTapContext>
                    .fromOpaque(MTAudioProcessingTapGetStorage(tap)).release()
            },
            prepare: { tap, maxFrames, format in
                let context = Unmanaged<AudioTapContext>
                    .fromOpaque(MTAudioProcessingTapGetStorage(tap)).takeUnretainedValue()
                context.prepare(
                    channelCount: Int(format.pointee.mChannelsPerFrame),
                    sampleRate: format.pointee.mSampleRate, maxFrames: Int(maxFrames),
                    formatFlags: format.pointee.mFormatFlags,
                    bitsPerChannel: format.pointee.mBitsPerChannel)
            },
            unprepare: { tap in
                Unmanaged<AudioTapContext>
                    .fromOpaque(MTAudioProcessingTapGetStorage(tap))
                    .takeUnretainedValue().unprepare()
            },
            process: { tap, numberFrames, _, bufferListInOut, numberFramesOut, flagsOut in
                let context = Unmanaged<AudioTapContext>
                    .fromOpaque(MTAudioProcessingTapGetStorage(tap)).takeUnretainedValue()
                var timeRange = CMTimeRange()
                // The source audio must be fetched even when nothing will be
                // done to it: this call is what hands the buffer on.
                guard MTAudioProcessingTapGetSourceAudio(
                    tap, numberFrames, bufferListInOut, flagsOut, &timeRange,
                    numberFramesOut) == noErr
                else {
                    numberFramesOut.pointee = 0
                    return
                }
                // `MTAudioProcessingTapFlags` is a plain bit field, not an
                // `OptionSet`: the header declares it `uint32_t`.
                let startOfStream =
                    flagsOut.pointee & MTAudioProcessingTapFlags(
                        kMTAudioProcessingTapFlag_StartOfStream) != 0
                context.process(
                    bufferListInOut, frames: Int(numberFramesOut.pointee),
                    time: timeRange.start, startOfStream: startOfStream)
            })

        var tap: MTAudioProcessingTap?
        guard MTAudioProcessingTapCreate(
            kCFAllocatorDefault, &callbacks, kMTAudioProcessingTapCreationFlag_PreEffects,
            &tap) == noErr
        else {
            // The context was retained for a tap that does not exist.
            Unmanaged<AudioTapContext>.fromOpaque(context).release()
            return nil
        }
        return tap
    }
}

import Accelerate
import Foundation

/// ITU-R BS.1770-4 integrated loudness and true peak, plus the arithmetic
/// that turns a measurement into an export gain (road map 2, phase 5).
///
/// **Why this file has no AVFoundation in it.** `AudioDSP.swift`'s rule
/// applied to measurement: plain buffers in, a value type out, no player, no
/// reader, no tap. `Exporter.measureLoudness` is the one place that knows
/// where the samples come from, which is what lets the meter be exercised
/// against synthesized tones — the EBU Tech 3341 cases are *specified
/// signals*, so a check needs no fixture file at all.
///
/// **What the standard asks for, and where each number comes from.** Every
/// constant below is quoted from Recommendation ITU-R BS.1770-4 (10/2015)
/// with its table, and the coefficients are for a **48 kHz** sample rate —
/// the only rate the standard publishes them at, and the rate
/// `ExportWriter.decodedAudioSettings` pins the export mix to. That is why
/// `LoudnessMeter.init` REFUSES any other rate rather than filtering with
/// the wrong numbers: `AudioTapContext.prepare` is the precedent for
/// checking a format instead of assuming it.
///
/// The measurement chain is:
///
/// 1. **K-weighting** — two biquads in series (Tables 1 and 2), run
///    CONTINUOUSLY over the whole programme, never reset per block.
/// 2. **Gating blocks** — 400 ms at 75 % overlap, i.e. a new block every
///    100 ms, each block's mean square `z` summed over channels with the
///    Table 3 weights.
/// 3. **Two gates** — the absolute Γa = −70 LUFS, then the relative
///    Γr = (the gated mean's loudness) − 10 LU, applied ONCE.
/// 4. **True peak** — the UNWEIGHTED signal through the standard's 4-phase
///    12-tap interpolating FIR (Annex 2, § 3), taking the largest magnitude
///    over every phase and every channel.
///
/// **The self-checks that prove the coefficients were typed correctly**, all
/// measured against this implementation while it was written, over
/// synthesized tones fed in 1 013-frame pieces so that buffer edges are
/// exercised too:
///
/// | check | the standard says | measured here |
/// |---|---|---|
/// | K-weighting gain at 1 kHz | +0.6977 dB | **+0.6977 dB** |
/// | 0 dBFS 997 Hz sine in ONE channel of a stereo pair | −3.01 LKFS | −3.010 LUFS |
/// | the same sine in BOTH channels | 0.00 LKFS | 0.000 LUFS |
/// | EBU Tech 3341 case 1 (20 s stereo 1 kHz at 10^(−23/20)) | −23.0 LUFS | −22.993 LUFS |
/// | case 3, the relative gate (10 s @ −36, 60 s @ −23, 10 s @ −36) | −23.0 LUFS | −23.014 LUFS |
/// | case 4, the absolute gate (10 s @ −72, 60 s @ −23, 10 s @ −72) | −23.0 LUFS | −23.015 LUFS |
/// | case 5 (20 s @ −26, 20.1 s @ −20, 20 s @ −26) | −23.0 LUFS | −22.979 LUFS |
///
/// The first row is the one that catches a mistyped digit: the +0.6977 dB is
/// exactly what the standard's −0.691 offset exists to cancel (its Note 1
/// says so), so a wrong coefficient moves it and every row under it. The
/// second is the standard's own calibration sentence, quoted from § 2.1 of
/// Annex 1, and it is the tighter check of the two — it is stated at 997 Hz,
/// which is the frequency the offset cancels EXACTLY. The Tech 3341 cases
/// are all built on a 1 kHz tone, where the weighting is +0.6977 dB against
/// an offset of 0.691, so a pure 1 kHz fixture reads 0.007 LU high by
/// construction; that is the whole of the residual above, and it is not
/// error. The gating cases sit a further 0.02 LU away because their −36 and
/// −72 flanks contribute the blocks that straddle each transition.
///
/// **What this meter can and cannot promise.** Integrated loudness has no
/// slop: the rows above are within 0.03 LU of a number the standard states
/// to one decimal. True peak does — a 4× oversampler can miss an
/// inter-sample peak that falls between two of its own output instants, and
/// the standard's own Appendix 1 puts that under-read at up to 0.554 dB for
/// content at 0.45 × fs. Measured here on 45°-phase sines at amplitude 0.5
/// (analytic true peak −6.021 dBFS): 1 kHz reads −6.014, 4 kHz −5.821 and
/// fs/4 −5.938 — i.e. this meter reads at most 0.2 dB HIGH and never low.
/// `ffmpeg -af ebur128=peak=true` reads the same three tones −6.0, −5.7 and
/// −5.4, so two conforming meters are half a decibel apart at fs/4 and this
/// one is the closer of the two to the analytic answer. So "true peak never
/// exceeds −1 dBTP" is a claim about THIS meter, a proof that compares it to
/// another needs about ±0.7 dB near fs/4 (±0.1 dB against an analytic tone),
/// and the export sheet's copy says the ceiling is measured rather than
/// enforced by a limiter.
///
/// **A property of the standard's own filter, measured and worth knowing
/// before someone "fixes" the table.** The four phases of the interpolating
/// FIR do NOT have equal DC gain: their coefficients sum to 1.001587,
/// 0.973022, 0.973022 and 1.001587 respectively — 0.25 dB of ripple between
/// phases, and 0.111 dB shy of unity overall. That is what the standard
/// prints (it offers the table as "one set of filter coefficients … that
/// would satisfy the requirements", not as the only one), and it is
/// transcribed here verbatim rather than normalised, because a table quoted
/// from its source can be checked against that source and a table adjusted
/// by hand cannot. The consequence is bounded and handled: an inter-sample
/// peak that lands on phase 1 or 2 can read up to 0.24 dB low, and a peak
/// that lands ON a sample would read 0.11 dB low, which is why
/// [`LoudnessReport.truePeakDBTP`] is never allowed below the sample peak —
/// the reconstructed waveform passes exactly through every sample, so the
/// true peak is at least the sample peak by definition rather than by
/// measurement.

// MARK: - What a measurement says

/// The answer one pass over a programme gives.
///
/// `integratedLUFS` is optional because "no integrated loudness" is a real
/// state rather than an error: a programme shorter than one 400 ms block
/// yields no block at all, and digital silence has every block gated out by
/// Γa. The caller's answer to nil is "apply no gain and say so", never
/// reaching for −∞ and multiplying by it.
struct LoudnessReport: Equatable {
    /// Integrated loudness in LUFS (the standard spells the unit LKFS; they
    /// are the same number), or nil when every gating block was gated out.
    let integratedLUFS: Double?
    /// The largest interpolated magnitude, in dB relative to full scale.
    /// `-Double.infinity` for digital silence.
    let truePeakDBTP: Double
    /// The largest sample magnitude, in dBFS. Free from the same pass, and
    /// the invariant `truePeakDBTP >= samplePeakDBFS` holds by construction.
    let samplePeakDBFS: Double

    /// Digital silence: nothing to measure and nothing to normalise.
    static let silence = LoudnessReport(
        integratedLUFS: nil, truePeakDBTP: -.infinity, samplePeakDBFS: -.infinity)
}

// MARK: - What an export did about it

/// A measurement, the target it was measured against, and the gain that
/// follows — the value both consumers of an export read (the progress
/// sheet's final line and the `export` tool's result).
///
/// **Gain only, no limiter.** That is what makes every number here
/// arithmetic instead of a second measurement: a scalar gain shifts
/// integrated loudness and true peak by exactly itself, so "measured plus
/// the gain" IS what the file holds. Add a limiter, a soft clip or a
/// fader-shaped ramp and the reported figure becomes a guess.
///
/// **With one exception:** a mix past full scale written with NO gain is
/// clipped by the write pass's 16-bit decode, so the file holds a signal the
/// measurement never saw. `mixClipped` is that case, it is the only one, and
/// `summary` names it rather than letting the figures pass as the file's. A
/// gained export reads the same float mix the measurement read and is
/// quantised once, after the gain (spec §11 #86), so it is not clipped.
struct ExportLoudness: Equatable {
    /// What the mix measured, before any gain.
    let measured: LoudnessReport
    /// The integrated target that was asked for, or nil when the export was
    /// not normalised at all and this is a readout.
    let target: Double?
    /// The true-peak ceiling the gain was capped against.
    let ceiling: Double
    /// The gain that was applied, in dB. Quantised (see `gainStepDB`), and
    /// exactly 0 when nothing was applied.
    let gainDB: Double
    /// True when the ceiling, not the target, decided the gain — the case
    /// worth reporting, because the file will then be quieter than asked.
    let cappedByPeak: Bool

    /// The ceiling assumed when a caller asks for a target and names none.
    /// 0 dBTP is not a loudness opinion, it is "do not push the programme
    /// past full scale", which is true of every file: the export sheet always
    /// sends `peakCeilingDBTP`, and only a script can reach this default.
    static let fullScaleCeiling: Double = 0

    /// The grid the applied gain is rounded to, in dB.
    ///
    /// Not cosmetic. AVFoundation's mix is not bit-deterministic near a duck
    /// ramp edge (CLAUDE.md records 38 samples of one 16-bit LSB), which
    /// moves the measured loudness by something like 10⁻⁵ LU — irrelevant to
    /// a ±0.5 LU target, but enough that a raw `Double` gain would differ in
    /// its last bits between two runs and round the ENTIRE file's 16-bit
    /// samples differently. At 0.01 dB the two runs pick the same gain, so
    /// two normalised exports of one project compare, and "−14.0 LUFS"
    /// reproduces.
    static let gainStepDB: Double = 0.01

    /// The linear multiplier `ExportWriter` applies to the decoded samples.
    var linearGain: Double { pow(10, gainDB / 20) }

    /// True when the writer has nothing to do — which is what keeps an
    /// un-normalised export on exactly the code path it had before this
    /// phase existed.
    var isUnity: Bool { gainDB == 0 }

    /// What the file holds: the measurement shifted by the gain — unless
    /// `mixClipped`, which is the one case where it does not.
    var integratedLUFS: Double? { measured.integratedLUFS.map { $0 + gainDB } }
    var truePeakDBTP: Double { measured.truePeakDBTP + gainDB }

    /// True when the mix passed full scale and is written with NO gain — the
    /// one case where the two lines above describe the MIX and not the file.
    ///
    /// The measurement reads 32-bit float on purpose (`ExporterLoudness` says
    /// why), and so does the write pass whenever a gain applies (spec §11
    /// #86), so a gained export is the measured signal turned down. An
    /// export with no gain is written from the 16-bit decode, which
    /// SATURATES: for a mix past full scale the file holds it hard-clipped,
    /// and no arithmetic here can carry the measurement into that, because a
    /// clip is not a gain. The decode is kept for those exports because
    /// changing it would change every such file's bytes, so `summary` names
    /// the overshoot and says whose numbers these are.
    ///
    /// A gain of exactly 0 dB is `isUnity`, and the writer then applies none.
    var mixClipped: Bool { measured.samplePeakDBFS > 0 && isUnity }

    /// The gain a `target` and a `ceiling` ask for over `measured`.
    ///
    /// `target` nil is "do not normalise": the measurement is still carried,
    /// because the road map wants every export's final line to report what
    /// the file actually holds, normalised or not.
    static func resolve(
        measured: LoudnessReport, target: Double?, ceiling: Double?
    ) -> ExportLoudness {
        let ceiling = ceiling ?? fullScaleCeiling
        guard let target = target, let integrated = measured.integratedLUFS else {
            return ExportLoudness(
                measured: measured, target: target, ceiling: ceiling, gainDB: 0,
                cappedByPeak: false)
        }
        let wanted = target - integrated
        // The cap is computed on TRUE peak rather than sample peak, and that
        // is what makes the write safe as well as honest: true peak is never
        // below sample peak, so a gain that keeps the true peak under the
        // ceiling keeps every 16-bit sample inside full scale, and the clip
        // in the writer's quantiser (`ExportAudioGain`) never has to fire.
        //
        // A peak that is not a finite number is NO headroom, which is the
        // safe answer and not the obvious one. −∞ cannot reach this line at
        // all — a nil `integratedLUFS` has already returned above, and a
        // programme with any block above Γa has a non-zero sample peak — so
        // the only value that gets here is a +∞ carried in from float source
        // media holding a non-finite sample, and "the peak cannot be
        // measured" has to mean "do not push it up". Infinite headroom would
        // mean the opposite: apply the whole requested boost and ignore the
        // ceiling.
        let headroom = measured.truePeakDBTP.isFinite ? ceiling - measured.truePeakDBTP : 0
        // The two are quantised DIFFERENTLY, because they mean different
        // things. `wanted` is a target and rounds to nearest: half a
        // hundredth of a decibel either way of a ±0.5 LU claim is nothing.
        // `headroom` is a CONSTRAINT — rounding it to nearest hands back up
        // to 0.005 dB of the attenuation the ceiling asked for, and a
        // ceiling-capped export then reports, and holds, a true peak ABOVE
        // the ceiling it names about half the time (which is what the sheet's
        // "capped so its true peak stays under −1 dBTP" would then be
        // promising falsely). It rounds DOWN, toward more attenuation, so the
        // shifted true peak can only land at or under the ceiling.
        let quantised = Swift.min(
            (wanted / gainStepDB).rounded() * gainStepDB,
            (headroom / gainStepDB).rounded(.down) * gainStepDB)
        return ExportLoudness(
            measured: measured, target: target, ceiling: ceiling,
            gainDB: quantised.isFinite ? quantised : 0, cappedByPeak: headroom < wanted)
    }

    /// The one line every export reports: `"Peak −1.0 dBTP · −14.0 LUFS"`.
    var summary: String {
        guard truePeakDBTP.isFinite else {
            // −∞ is digital silence. Anything else non-finite is a mix
            // carrying a non-finite sample, and calling THAT silent is the
            // loudest lie this line could tell.
            return truePeakDBTP == -.infinity
                ? "Silent" : "Peak not measurable (a non-finite sample in the mix)"
        }
        let peak = "Peak \(Self.decibels(truePeakDBTP)) dBTP"
        let measurement: String
        if let integrated = integratedLUFS {
            measurement = "\(peak) · \(Self.decibels(integrated)) LUFS"
        } else {
            // A programme shorter than one 400 ms gating block, or one whose
            // every block fell under Γa. It has a peak and no loudness, and
            // saying which is better than printing −∞.
            measurement = "\(peak) · loudness not measurable"
        }
        guard mixClipped else { return measurement }
        // The figures are the mix's and the file's are worse, so the line
        // says which it is showing — in both consumers at once, since the
        // progress sheet's last line and the `export` tool's result are the
        // same string. `mixClipped` says why they differ at all.
        return "\(measurement) — measured on the mix, which clipped at +"
            + "\(Self.decibels(measured.samplePeakDBFS)) dBFS before it was written"
    }

    /// One decimal, with the typographic minus the rest of the chrome uses.
    private static func decibels(_ value: Double) -> String {
        String(format: "%.1f", value).replacingOccurrences(of: "-", with: "−")
    }
}

// MARK: - The meter

/// BS.1770-4 over a stream of interleaved 32-bit float frames.
///
/// Feed it every frame of the programme in order, then ask it once. The
/// K-weighting filters and the true-peak interpolator both carry state
/// ACROSS calls — that is the whole reason this is an object and not a
/// function: the filters run continuously over the programme (blocks
/// overlap by 75 %, so a per-block reset is not even well defined) and the
/// interpolating FIR needs 11 samples of per-channel history, which arrive
/// in one buffer and are needed in the next.
final class LoudnessMeter {

    /// The rate the coefficient tables are published at, and the rate the
    /// export mix is decoded at. Not a default: `init` refuses anything else.
    static let requiredSampleRate: Double = 48000

    /// Every measurement window BS.1770-4 § 2 names, in seconds.
    ///
    /// A gating block is 400 ms; blocks overlap by 75 %, so one starts every
    /// 100 ms and a block is exactly four consecutive 100 ms sub-blocks. That
    /// is why the accumulator below keeps a running sum per sub-block and a
    /// ring of the last four rather than re-summing 19 200 samples per block.
    private static let blockSeconds: Double = 0.400
    private static let hopSeconds: Double = 0.100
    private static let subBlocksPerBlock = 4

    /// BS.1770-4 equation (2)'s offset. Note 1 of that clause says what it
    /// is for: it cancels the K-weighting's gain at 997 Hz, which this
    /// implementation measures as +0.6977 dB.
    private static let offset: Double = -0.691

    /// Γa, the absolute gate, in LUFS. A block at or below it is not
    /// programme.
    private static let absoluteGate: Double = -70

    /// Γr's offset below the gated mean, in LU.
    private static let relativeGate: Double = -10

    // ---- K-weighting -----------------------------------------------------

    /// One biquad, in the difference equation BS.1770-4's Fig. 3 draws:
    ///
    ///     y[n] = b0·x[n] + b1·x[n−1] + b2·x[n−2] − a1·y[n−1] − a2·y[n−2]
    ///
    /// `a0` is 1 in both of the standard's tables and is not carried.
    ///
    /// Double, not Float, and deliberately: the second stage's poles sit at
    /// a1 = −1.99005, a2 = 0.99007 — a hair from DC — and a single-precision
    /// direct form I loses enough per step to drift audibly over a
    /// forty-minute programme. This is not the audio render thread, so the
    /// precision is free.
    private struct Biquad {
        let b0: Double, b1: Double, b2: Double, a1: Double, a2: Double
    }

    /// Table 1: "Filter coefficients for stage 1 of the pre-filter to model a
    /// spherical head" — a high shelf, +4 dB above about 2 kHz. Quoted from
    /// Recommendation ITU-R BS.1770-4 (10/2015), for 48 kHz.
    private static let stage1 = Biquad(
        b0: 1.535_124_859_586_97,
        b1: -2.691_696_189_406_38,
        b2: 1.198_392_810_852_85,
        a1: -1.690_659_293_182_41,
        a2: 0.732_480_774_215_85)

    /// Table 2: "Filter coefficients for the second stage weighting curve" —
    /// the RLB high-pass. Same source, same rate.
    private static let stage2 = Biquad(
        b0: 1.0,
        b1: -2.0,
        b2: 1.0,
        a1: -1.990_047_454_833_98,
        a2: 0.990_072_250_366_21)

    // ---- true peak -------------------------------------------------------

    /// Taps per phase of the interpolating FIR.
    private static let peakTaps = 12
    private static let peakPhases = 4

    /// Annex 2, § 3: "One set of filter coefficients (for the order 48,
    /// 4-phase, FIR interpolating) that would satisfy the requirements would
    /// be as follows", transcribed COLUMN BY COLUMN from the standard's own
    /// table — phase 0 first, tap 0 first — so it can be read back against
    /// the printed page a row at a time.
    ///
    /// Phase 3 is phase 0 reversed and phase 2 is phase 1 reversed, which is
    /// the linear-phase symmetry a correct transcription has and a mistyped
    /// one does not; the file's header records the DC gains the four phases
    /// actually have, which is the check that is NOT satisfied and is a
    /// property of the standard's set rather than of this copy of it.
    ///
    /// The standard's first processing step, a 12.04 dB attenuation, is
    /// omitted on the standard's own instruction: "This step is not necessary
    /// if the calculations are performed in floating point." So is the
    /// matching amplification, which is what it was for.
    private static let peakFilter: [[Double]] = [
        [
            0.001_708_984_375_0, 0.010_986_328_125_0, -0.019_653_320_312_5,
            0.033_203_125_000_0, -0.059_448_242_187_5, 0.137_329_101_562_5,
            0.972_167_968_750_0, -0.102_294_921_875_0, 0.047_607_421_875_0,
            -0.026_611_328_125_0, 0.014_892_578_125_0, -0.008_300_781_250_0,
        ],
        [
            -0.029_174_804_687_5, 0.029_296_875_000_0, -0.051_757_812_500_0,
            0.089_111_328_125_0, -0.166_503_906_250_0, 0.465_087_890_625_0,
            0.779_785_156_250_0, -0.200_317_382_812_5, 0.101_562_500_000_0,
            -0.058_227_539_062_5, 0.033_081_054_687_5, -0.018_920_898_437_5,
        ],
        [
            -0.018_920_898_437_5, 0.033_081_054_687_5, -0.058_227_539_062_5,
            0.101_562_500_000_0, -0.200_317_382_812_5, 0.779_785_156_250_0,
            0.465_087_890_625_0, -0.166_503_906_250_0, 0.089_111_328_125_0,
            -0.051_757_812_500_0, 0.029_296_875_000_0, -0.029_174_804_687_5,
        ],
        [
            -0.008_300_781_250_0, 0.014_892_578_125_0, -0.026_611_328_125_0,
            0.047_607_421_875_0, -0.102_294_921_875_0, 0.972_167_968_750_0,
            0.137_329_101_562_5, -0.059_448_242_187_5, 0.033_203_125_000_0,
            -0.019_653_320_312_5, 0.010_986_328_125_0, 0.001_708_984_375_0,
        ],
    ]

    // ---- shape -----------------------------------------------------------

    private let channelCount: Int
    /// Frames in one 100 ms sub-block, and the largest chunk `process`
    /// handles: a chunk never straddles a sub-block boundary, which is what
    /// lets one accumulator serve every channel.
    private let hopFrames: Int
    private let blockFrames: Int

    /// One channel's samples for the current chunk, with the previous
    /// chunk's last 11 frames in front of them — the history the
    /// interpolating FIR needs across a buffer edge, and the reason a
    /// per-buffer implementation misses every inter-sample peak that
    /// straddles one (buffer edges arrive about a thousand times a minute).
    private let channelBuffer: UnsafeMutablePointer<Double>
    /// One phase's interpolated output for the current chunk.
    private let phaseBuffer: UnsafeMutablePointer<Double>
    /// `peakTaps − 1` raw samples per channel, carried between chunks.
    private let peakHistory: UnsafeMutablePointer<Double>
    /// Four coefficients per phase, REVERSED, because `vDSP_convD` computes
    /// a correlation (`C[n] = Σ A[n+p]·F[p]`) and a filter is the same sum
    /// with the taps the other way round. Derived here rather than typed
    /// again, so the literal above stays the only transcription.
    private let peakCoefficients: UnsafeMutablePointer<Double>
    /// Two sections of `x[n−1], x[n−2], y[n−1], y[n−2]`, per channel.
    private let filterState: UnsafeMutablePointer<Double>
    /// Int16 arrives from the fallback decode; the converted floats land
    /// here. `nil` until something asks, since the float path never does.
    private var int16Scratch: UnsafeMutablePointer<Float>?
    private var int16Capacity = 0

    /// Σ over channels of Σ y² for the sub-block being filled.
    private var subBlockSum: Double = 0
    private var subBlockFilled = 0
    /// The last four sub-block sums, oldest overwritten.
    private var ring: [Double]
    private var ringWrites = 0
    /// One `Σᵢ Gᵢ·zᵢ` per completed 400 ms block. 100 ms apart, so ten a
    /// second — 36 000 doubles for an hour of programme, which is why the
    /// two-sweep gating can keep them all.
    private var blocks: [Double] = []

    private var truePeakLinear: Double = 0
    private var samplePeakLinear: Double = 0

    /// nil for a rate the coefficients are not published at, or a channel
    /// count this build cannot weight.
    ///
    /// **Both refusals are assertions, not conveniences.** The K-weighting
    /// table is 48 kHz only, and filtering at another rate would answer a
    /// number that looks right and is not. And BS.1770-4's Table 3 weights
    /// the surround channels 1.41 and excludes the LFE, which needs a
    /// channel LAYOUT this meter is not handed; mono and stereo are the two
    /// cases whose weights are all 1.0 and therefore need no layout, and the
    /// export mix is stereo by `ExportWriter.decodedAudioSettings`. A
    /// surround measurement is a feature, not a widening of this guard.
    init?(sampleRate: Double, channelCount: Int) {
        guard sampleRate == Self.requiredSampleRate, (1...2).contains(channelCount) else {
            return nil
        }
        self.channelCount = channelCount
        hopFrames = Int((sampleRate * Self.hopSeconds).rounded())
        blockFrames = hopFrames * Self.subBlocksPerBlock
        guard hopFrames > Self.peakTaps else { return nil }

        let taps = Self.peakTaps
        channelBuffer = .allocate(capacity: hopFrames + taps - 1)
        channelBuffer.initialize(repeating: 0, count: hopFrames + taps - 1)
        phaseBuffer = .allocate(capacity: hopFrames)
        phaseBuffer.initialize(repeating: 0, count: hopFrames)
        peakHistory = .allocate(capacity: channelCount * (taps - 1))
        peakHistory.initialize(repeating: 0, count: channelCount * (taps - 1))
        peakCoefficients = .allocate(capacity: Self.peakPhases * taps)
        peakCoefficients.initialize(repeating: 0, count: Self.peakPhases * taps)
        for (index, phase) in Self.peakFilter.enumerated() {
            for (tap, value) in phase.reversed().enumerated() {
                peakCoefficients[index * taps + tap] = value
            }
        }
        filterState = .allocate(capacity: channelCount * 8)
        filterState.initialize(repeating: 0, count: channelCount * 8)
        ring = Array(repeating: 0, count: Self.subBlocksPerBlock)
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("LoudnessMeter does not support NSCoder")
    }

    deinit {
        channelBuffer.deallocate()
        phaseBuffer.deallocate()
        peakHistory.deallocate()
        peakCoefficients.deallocate()
        filterState.deallocate()
        int16Scratch?.deallocate()
    }

    // MARK: - Feeding

    /// `frames` interleaved frames of 32-bit float, in programme order.
    func feed(_ samples: UnsafePointer<Float>, frames: Int) {
        var offset = 0
        while offset < frames {
            // Never across a sub-block boundary, and never more than one
            // sub-block: the accumulator then belongs to exactly one
            // sub-block for the whole chunk, whichever channel is being
            // walked.
            let take = Swift.min(hopFrames - subBlockFilled, frames - offset)
            process(samples + offset * channelCount, frames: take)
            offset += take
        }
    }

    /// The same, for the 16-bit fallback decode: `AVAssetReaderAudioMixOutput`
    /// is asked for float first and this is what a refusal falls back to
    /// (`Exporter.measureAudioSettings`). Scaled by 1/32768 so full scale is
    /// 1.0, which is what every threshold above is expressed in.
    func feedInt16(_ samples: UnsafePointer<Int16>, frames: Int) {
        let count = frames * channelCount
        guard count > 0 else { return }
        if int16Capacity < count {
            int16Scratch?.deallocate()
            int16Scratch = .allocate(capacity: count)
            int16Capacity = count
        }
        guard let scratch = int16Scratch else { return }
        var scale = Float(1.0 / 32768.0)
        vDSP_vflt16(samples, 1, scratch, 1, vDSP_Length(count))
        vDSP_vsmul(scratch, 1, &scale, scratch, 1, vDSP_Length(count))
        feed(scratch, frames: frames)
    }

    /// One chunk, wholly inside one sub-block.
    private func process(_ samples: UnsafePointer<Float>, frames: Int) {
        guard frames > 0 else { return }
        let taps = Self.peakTaps
        let history = taps - 1
        let stride = vDSP_Stride(channelCount)

        var chunkPeak: Float = 0
        vDSP_maxmgv(samples, 1, &chunkPeak, vDSP_Length(frames * channelCount))
        samplePeakLinear = Swift.max(samplePeakLinear, Double(chunkPeak))

        for channel in 0..<channelCount {
            // The channel's history, then its new samples: one contiguous
            // run of `history + frames` doubles, which is exactly what both
            // the interpolator and the biquads want.
            channelBuffer.update(from: peakHistory + channel * history, count: history)
            vDSP_vspdp(
                samples + channel, stride, channelBuffer + history, 1, vDSP_Length(frames))

            // True peak, on the UNWEIGHTED samples. Feeding K-weighted ones
            // here is an easy wiring mistake and reads up to 4 dB high on
            // bright material.
            for phase in 0..<Self.peakPhases {
                vDSP_convD(
                    channelBuffer, 1, peakCoefficients + phase * taps, 1, phaseBuffer, 1,
                    vDSP_Length(frames), vDSP_Length(taps))
                var peak: Double = 0
                vDSP_maxmgvD(phaseBuffer, 1, &peak, vDSP_Length(frames))
                truePeakLinear = Swift.max(truePeakLinear, peak)
            }

            // Before the filtering, which overwrites the same run: the last
            // `history` RAW samples are the next chunk's history.
            (peakHistory + channel * history).update(
                from: channelBuffer + frames, count: history)

            weight(channelBuffer + history, frames: frames, channel: channel)
            var sum: Double = 0
            vDSP_svesqD(channelBuffer + history, 1, &sum, vDSP_Length(frames))
            // Table 3's Gᵢ is 1.0 for left, right and centre, so the sum over
            // channels needs no weight at all here; `init` is where the
            // channel counts that would need one are refused.
            subBlockSum += sum
        }

        subBlockFilled += frames
        if subBlockFilled >= hopFrames { closeSubBlock() }
    }

    /// The two-stage K-weighting, in place, with this channel's state.
    private func weight(_ samples: UnsafeMutablePointer<Double>, frames: Int, channel: Int) {
        let base = filterState + channel * 8
        for (index, section) in [Self.stage1, Self.stage2].enumerated() {
            let state = base + index * 4
            var x1 = state[0], x2 = state[1], y1 = state[2], y2 = state[3]
            for n in 0..<frames {
                let x = samples[n]
                let y = section.b0 * x + section.b1 * x1 + section.b2 * x2
                    - section.a1 * y1 - section.a2 * y2
                x2 = x1
                x1 = x
                y2 = y1
                y1 = y
                samples[n] = y
            }
            state[0] = x1
            state[1] = x2
            state[2] = y1
            state[3] = y2
        }
    }

    private func closeSubBlock() {
        ring[ringWrites % Self.subBlocksPerBlock] = subBlockSum
        ringWrites += 1
        subBlockSum = 0
        subBlockFilled = 0
        guard ringWrites >= Self.subBlocksPerBlock else { return }
        blocks.append(ring.reduce(0, +) / Double(blockFrames))
    }

    // MARK: - The answer

    /// The gated integrated loudness and the true peak.
    ///
    /// A trailing partial block is discarded, which the standard requires and
    /// which means a programme shorter than 400 ms has no integrated loudness
    /// at all.
    ///
    /// **A non-finite sample is not defended against here**, and what it does
    /// is worth knowing before someone reads a strange number as a bug in the
    /// filter: a NaN is dropped by both peak accumulators (`Swift.max` keeps
    /// the accumulator when the new value is NaN) but poisons the biquad
    /// state, so every later block is NaN and is dropped by `integrated`'s
    /// `$0 > 0`, leaving the integrated figure that of the programme up to
    /// that sample; an infinity survives into `truePeakDBTP` as +∞. Neither
    /// is silently normalised, and neither can push a file up:
    /// `ExportLoudness.resolve` reads a non-finite peak as NO headroom, and
    /// `summary` says the peak could not be measured rather than calling the
    /// programme silent.
    func finish() -> LoudnessReport {
        let peak = Swift.max(truePeakLinear, samplePeakLinear)
        return LoudnessReport(
            integratedLUFS: integrated(),
            truePeakDBTP: Self.decibels(peak),
            samplePeakDBFS: Self.decibels(samplePeakLinear))
    }

    /// BS.1770-4 equations (5)–(7): the absolute gate, then the relative one,
    /// applied ONCE.
    ///
    /// The mean is over the LINEAR mean squares, never over the block
    /// loudnesses. Both gates are expressed in dB, which invites averaging
    /// dB; the gates only SELECT blocks, and the answer is the loudness of
    /// the survivors' linear mean.
    private func integrated() -> Double? {
        let gated = blocks.filter { $0 > 0 && Self.loudness($0) > Self.absoluteGate }
        guard !gated.isEmpty else { return nil }
        let threshold = Self.loudness(gated.reduce(0, +) / Double(gated.count))
            + Self.relativeGate
        let kept = gated.filter { Self.loudness($0) > threshold }
        guard !kept.isEmpty else { return nil }
        return Self.loudness(kept.reduce(0, +) / Double(kept.count))
    }

    /// A weighted mean square as a loudness, BS.1770-4 equation (2).
    private static func loudness(_ meanSquare: Double) -> Double {
        guard meanSquare > 0 else { return -.infinity }
        return offset + 10 * log10(meanSquare)
    }

    private static func decibels(_ linear: Double) -> Double {
        linear > 0 ? 20 * log10(linear) : -.infinity
    }
}

//! The per-clip property types of spec §5.2 — the `video`, `audio`, `text`
//! and `shape` groups a [`crate::model::Clip`] carries, and every struct
//! and enum inside them but three families, all re-exported below: the
//! region types, which are `model_regions.rs`'s, the text types, which are
//! `model_text.rs`'s, and the shape types, which are `model_shape.rs`'s.
//!
//! Split out of `model.rs` under the size rule (core/CLAUDE.md: a module
//! over ~600 lines gives something up before it takes anything on), and
//! split HERE because the property types are a concern of their own:
//! `model.rs` is the document's skeleton — project, media, tracks, clips,
//! nests, actions — while this file is what the four `set_*` patches in
//! `edit_props.rs` deep-merge into, what `actions.rs` interpolates, and
//! what the compositor's uniforms are read from. Reading one is reading the
//! schema's SHAPE; reading the other is reading its VOCABULARY.
//!
//! It has since paid the same rule THREE times itself, and every payment was
//! made before the phase that owed them took anything on. Road map 2's
//! phase 3c added `video.obscure` and its two types, which took the file to
//! 633 lines, so the boxes drawn ON the picture — [`Spotlight`],
//! [`ObscureRegion`], [`SpotShape`] and [`MAX_OBSCURE`] — went out to
//! `model_regions.rs` first; they share one coordinate frame and one shape
//! enum, which is the seam, and that module's doc states the frame. Phase 6
//! arrived at 592 owing `video.blend` and `shape.gradient`, so the text
//! vocabulary — [`TextProps`], [`TextAlign`], [`TextVAlign`], [`Outline`],
//! [`Backdrop`], [`TextAnimation`] and [`TextAnimationKind`] — went out to
//! `model_text.rs` in the same way. Its seam is the one property group the
//! model cannot MEASURE, because only the platform can lay text out; that
//! module's doc states it. Road map 5's E2 arrived AT 600 owing
//! `video.motion`, so the shape vocabulary — [`ShapeProps`], [`ShapeKind`],
//! [`Stroke`], [`Gradient`], [`GradientKind`], [`GradientStop`] and
//! [`MAX_GRADIENT_STOPS`] — went out to `model_shape.rs`, which is the
//! alternative phase 6 weighed and refused for lack of room. Its seam is
//! the text one read a second time: shape and text are the two sources the
//! model only DESCRIBES, drawn on the CPU and keyed by the recipe's content
//! hash, where everything left here is read straight into the compositor's
//! uniform block.
//!
//! Every path stays as it was, through all four cuts: `model.rs`
//! re-exports this whole module with `pub use crate::model_props::*` and
//! this module re-exports the other three the same way, so
//! `crate::model::VideoProps`, `crate::model::Spotlight`,
//! `crate::model::TextProps`, `crate::model::ShapeProps` and the crate-root
//! re-exports in `lib.rs` are all untouched. The rules are `model.rs`'s
//! too — the field names ARE the
//! JSON keys, declaration order IS key order, every type is
//! `#[serde(default)]` over a hand-written [`Default`] that says what an
//! absent key means, and nothing here carries `deny_unknown_fields`.

