    /// The mix carries the plan's volume envelope AND, for any track whose
    /// clips use pan, the compressor or noise reduction, the
    /// `MTAudioProcessingTap` that runs them (`AudioTap.swift`). Those taps
    /// were long believed to be an AVPlayer-only feature — true of the
    /// `AVAssetExportSession` this pipeline replaced, and the reason the
    /// effects were left unimplemented — but measured against
    /// `AVAssetReaderAudioMixOutput` they run here as well: a tap that
== CompositionPlan.swift
import AppKit

// MARK: - Composition plan (spec §7.2)

/// One clip's contribution to a composition track. `duration !=
/// sourceDuration` is the signal to `scaleTimeRange` (speed and freeze).
struct PlanSegment: Codable, Equatable {
    let clip: UInt32
    let media: UInt32
    let sourceIn: Ticks
    let sourceDuration: Ticks
    let start: Ticks
    let duration: Ticks
    /// The time-pitch algorithm for a speed change, e.g. "spectral"; nil
    /// leaves AVFoundation's default.
    let pitch: String?
    /// A video segment's media's Camera Log (spec §11 GR-16), present only
    /// when the media converts: it makes the composition a converting one
    /// (`CompositionPlan.convertsMedia`).
    let input: MediaColor?
== ShapeProps.swift
import Foundation

// The shape group of the read-only mirror (spec §5.2's `shape`): a pure move
// out of `ProjectSnapshot.swift` (grading L3), whose decoding rules
// (`lenient`, snake-case) are stated at that file's head.

/// A shape's stroke.
struct StrokeProps: Codable, Equatable {
    var width: Double
    var color: RGBA

    init(width: Double = 6, color: RGBA = [1, 1, 1, 1]) {
        self.width = width
        self.color = color
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        width = c.lenient(.width, 6)
        color = c.lenient(.color, [1, 1, 1, 1])
== CurveProps.swift
import AppKit

// MARK: - The curves (spec §11 GR-12, grading-2 G2-3; GR-32, grading-4 T4-2)

/// One curve point, `[x, y]` in JSON (`model_grade.rs`'s `CurvePoint`): the
/// input and the output, each 0…1.
struct CurvePoint: Hashable, Codable {
    var x: Double
    var y: Double

    init(x: Double, y: Double) {
        self.x = x
        self.y = y
    }

    init(from decoder: Decoder) throws {
        var c = try decoder.unkeyedContainer()
        x = try c.decode(Double.self)
        y = try c.decode(Double.self)
    }

